-- Complete synthetic Class C demo FPO/farmer/farm data export.
-- Snapshot taken from the local MaatiTrace AI development database after farm geometry and location corrections.
-- Includes five login rows (Argon2id hashes only), FPO/farmer profiles, 20 farms, links, consents, events,
-- FPO service areas/commodities, current Class C assignment, and associated audit records.
-- Does NOT include class feature catalogues/plans, pipeline/analysis output, or plaintext passwords.
-- Keep this file private: it contains credential hashes and synthetic personal/contact data.
BEGIN;
SET LOCAL search_path = public, pg_catalog;
DO $seed_guard$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.users WHERE user_id = ANY(ARRAY['62f7885e-35c2-434c-afec-bb5b14428db9'::uuid])) THEN
    RAISE EXCEPTION 'One or more existing admin accounts referenced by approval/audit records are missing';
  END IF;
END $seed_guard$;

-- Five login identities (stored password hashes only; no plaintext passwords).

-- FPO profile, contact and final location details.

-- FPO owner membership.

-- FPO account-to-profile organization record.

-- Four farmer profiles.

-- FPO crop/commodity priorities.

-- Four service districts.

-- 20 farm records with polygon, area, H3 coverage, crop and final village/block names.

-- Twenty active consent-backed farmer-to-farm relationships.

-- Consent records for the relationships.

-- Relationship request, consent, and acceptance events.

-- Current FPO account class assignment only (no plan/features).

-- FPO profile update audit record.

-- Audit trail of fixture activation, class assignment, and farmer relationship decisions.

-- Summary verification queries
SELECT count(*) AS farm_count FROM public.farms WHERE fpo_id='2ce08e39-d17f-44bb-b3ee-5407d5e28a63'::uuid;
SELECT count(DISTINCT farmer_user_id) AS active_farmers FROM public.fpo_farmer_relationships WHERE fpo_id='512cf38e-2203-491f-abb8-6e6c82b45e1e'::uuid AND status='ACTIVE';
SELECT district_name,block_name,count(*) AS farms FROM public.farms WHERE fpo_id='2ce08e39-d17f-44bb-b3ee-5407d5e28a63'::uuid GROUP BY district_name,block_name ORDER BY district_name,block_name;
SELECT crop_name,count(*) AS farms FROM public.farms WHERE fpo_id='2ce08e39-d17f-44bb-b3ee-5407d5e28a63'::uuid GROUP BY crop_name ORDER BY crop_name;
COMMIT;
